<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\TemplateSnippet\Domain\Event;

use Override;
use Civi\Lughauth\Features\Document\TemplateSnippet\Domain\TemplateSnippet;

class TemplateSnippetEnableEvent extends TemplateSnippetUpdateEvent
{
    public function __construct(
        TemplateSnippet $payload,
        TemplateSnippet $original
    ) {
        parent::__construct($payload, $original);
    }
    #[Override]
    public function eventType(): string
    {
        return 'template-snippet.enable';
    }
    #[Override]
    public function schemaVersion(): string
    {
        return 'v1';
    }
    #[Override]
    public function payload(): array
    {
        return $this->payload->asPublicJson();
    }
    #[Override]
    public function original(): array
    {
        return $this->original->asPublicJson();
    }
}
